SELECT DISTINCT a.id, a.businessNo, b.username, a.businessType, a.price, a.businessContent, a.businessOrganization, a.createTime, a.businessStatus, # 总条数 (SELECT COUNT(DISTINCT a.id) FROM medical a JOIN user b ON a.createId = b.id
JOIN appointment d ON a.businessNo = d.appointNo JOIN doctor e ON d.doctorId = e.id
AND b.username like "%"#{username}"%"
AND e.doctor = #{doctor}
AND a.businessType = #{businessType}
AND a.businessOrganization like "%"#{businessOrganization}"%"
AND a.businessStatus= #{businessStatus}
AND a.createId = #{createId}
AND a.del_flag = 0
) AS total FROM medical a JOIN user b ON a.createId = b.id
JOIN appointment d ON a.businessNo = d.appointNo JOIN doctor e ON d.doctorId = e.id
AND b.username like "%"#{username}"%"
AND e.doctor = #{doctor}
AND a.businessType = #{businessType}
AND a.businessOrganization like "%"#{businessOrganization}"%"
AND a.businessStatus= #{businessStatus}
AND a.createId = #{createId}
AND a.del_flag = 0
ORDER BY a.id LIMIT #{pageStart},#{pageSize}

