1 = 1
AND a.drugName like "%"#{drugName}"%"
AND c.drugType = #{drugType} AND a.del_flag = 0 AND a.pharmacy_id = #{pharmacyId}
) AS total FROM drug a LEFT JOIN pharmacy b ON a.pharmacy_id = b.id LEFT JOIN drug_type c ON a.drugTypeId = c.id
1 = 1
AND a.drugName like "%"#{drugName}"%"
AND c.drugType = #{drugType} AND a.del_flag = 0 AND a.pharmacy_id = #{pharmacyId}

SELECT id AS doctorId,doctor
FROM doctor
WHERE
    hospitalId = #{hospitalId}
AND departmentId = #{departmentId}

SELECT id,hospitalName,address,registerTime
FROM hospital
WHERE id = #{id}
